fn part(a:[]i64,lo0:usize,hi:usize)usize{const p=a[hi];var i=lo0;for(lo0..hi)|j|{if(a[j]<p){std.mem.swap(i64,&a[i],&a[j]);i+=1;}}std.mem.swap(i64,&a[i],&a[hi]);return i;}
const std=@import("std");
export fn kthnumber(v:[*]const i64,n:usize)callconv(.c)i64{if(n<4 or n>19)return -1;const count=v[0];const mode=v[1];const k=v[2];if(count<1 or count>16 or n!=@as(usize,@intCast(count+3)) or (mode!=1 and mode!=2) or k<1 or k>count)return -1;var a:[16]i64=undefined;for(0..@intCast(count))|i|{a[i]=v[i+3];if(a[i] < -10000 or a[i]>10000)return -1;}const target:usize=@intCast(if(mode==1) k-1 else count-k);var lo:usize=0;var hi:usize=@intCast(count-1);while(lo<=hi){const q=part(a[0..@intCast(count)],lo,hi);if(q==target)return a[q];if(q<target){lo=q+1;}else{if(q==0)break;hi=q-1;}}return -1;}
